// Picks Sourcing rows that have never been scored (empty 'AI Moat Score') and
// groups them into batches, one Claude call per batch.
const BATCH_SIZE = 15;
const MAX_BATCHES = 12; // safety cap on Claude calls per run
const CRITERIA = "You are screening early-stage startups for a B2B-focused VC investor. Criteria, in order of importance:\n\n1. MOST IMPORTANT: the end customer must plausibly be large corporates / enterprise organizations \u2014\n   not consumers, not solo freelancers/creators, not small local businesses, not \"prosumer\" tools.\n   Think: a Fortune 500 / large enterprise procurement or ops team would realistically buy this.\n   If the target customer looks like SMBs, indie hackers, or individuals, REJECT regardless of anything else.\n\n2. REJECT anything in the \"AI agent\" category \u2014 AI agent platforms, agent frameworks, browser-automation\n   agents, autonomous-agent tooling, or generic LLM/GPT wrapper products. This category is explicitly\n   excluded no matter how good it looks otherwise.\n\n2b. REJECT aerospace, space, satellite, and drone-based startups entirely \u2014 not an area of interest for\n   this investor, regardless of moat or enterprise fit.\n\n3. A tangible link to the physical world (hardware, robotics, sensors, IoT, industrial/manufacturing\n   equipment, energy infrastructure, materials science, logistics/physical operations) is a BONUS, not a\n   requirement. Pure software is completely fine \u2014 do NOT reject or penalize a candidate just for being\n   software-only. What matters is criteria 1 (enterprise customer) and 4 (real moat), full stop.\n\n4. Must show a genuinely defensible moat: proprietary data/tech, deep domain complexity, regulatory or\n   compliance edge, hardware, network effects, or real technical depth. REJECT anything that looks like a\n   thin wrapper or generic CRUD app replicable in about a week of \"vibe coding\". Be strict \u2014 when in doubt, reject.\n\n5. Sector-agnostic beyond the above. Geography: Europe, UK, US, or Middle East (if unclear, lower confidence).\n   Very early stage (pre-seed/seed) is assumed \u2014 each candidate includes its source and founding info;\n   trust that pre-filtering (BetaList = launching now, Apollo = founded within the last ~18 months) already\n   handles stage, you don't need to re-derive it.";

const unscored = $input.all()
  .map(it => it.json)
  .filter(j => j['Organization Name'] && (j['AI Moat Score'] === '' || j['AI Moat Score'] === undefined || j['AI Moat Score'] === null));

const out = [];
for (let b = 0; b < unscored.length && out.length < MAX_BATCHES; b += BATCH_SIZE) {
  const rows = unscored.slice(b, b + BATCH_SIZE);
  const candidates = rows.map(r => ({
    id: r.row_number,
    name: r['Organization Name'],
    description: String(r['Description'] || '').slice(0, 600),
    website: r['Website'] || '',
    source: r['Source'] || '',
    funding_usd: r['Funding USD (parsed)'] || null,
  }));
  const prompt = CRITERIA
    + '\n\nHere are the candidate startups as a JSON array:\n'
    + JSON.stringify(candidates)
    + '\n\nReturn ONLY a JSON array (no prose, no markdown fences), one object per candidate, in this exact shape:\n'
    + '[{"id": 0, "company_name": "...", "pass": true|false, "enterprise_fit": true|false, "is_ai_agent": true|false, '
    + '"has_physical_component": true|false, "is_space_or_drone": true|false, "moat_score": 1-5, "geography_guess": "...", "reasoning": "one short sentence covering enterprise fit, physical component, and moat"}]\n'
    + '"id" must be echoed back EXACTLY as given in the input so results can be matched. "company_name" is the '
    + 'clean startup name only (e.g. from a news headline like "Acme raises $2M", company_name is "Acme") - '
    + 'strip any funding/news phrasing.\n'
    + 'moat_score reflects how defensible the product looks (5 = strong moat, 1 = trivially replicable). '
    + 'is_space_or_drone is true for any space, satellite, aerospace, drone, UAV or counter-drone company (including defence drones). '
    + 'pass must be false whenever enterprise_fit is false, is_ai_agent is true or is_space_or_drone is true, regardless of moat_score.';
  out.push({ json: { prompt, max_tokens: 4000, rows } });
}
return out;

// Zips each Claude batch result back to its sheet rows (by row_number) and builds
// the in-place update. Rejected candidates get AI Moat Score 0 so they are never
// re-scored and sort to the bottom; the real moat score stays visible in AI Notes.
const batches = $('Build Scoring Batches').all();
const NEWS_SOURCES = ['tech.eu', 'TechEU', 'Wamda'];
const out = [];
$input.all().forEach((item, i) => {
  const rows = (batches[i] && batches[i].json.rows) || [];
  const results = Array.isArray(item.json.result) ? item.json.result : [];
  const byId = {};
  for (const r of results) byId[String(r.id)] = r;
  for (const row of rows) {
    const r = byId[String(row.row_number)];
    if (!r) continue; // missing/malformed -> left unscored, retried next run
    const moat = Number(r.moat_score) || 0;
    // Hard rules enforced in code too: the model sometimes passes a drone company despite the criteria.
    const pass = r.pass === true && r.enterprise_fit !== false && r.is_ai_agent !== true && r.is_space_or_drone !== true;
    const upd = {
      row_number: row.row_number,
      'AI Moat Score': pass ? moat : 0,
      'AI Notes': (pass ? 'PASS' : 'REJECT') + ' (moat ' + moat + '/5) - ' + (r.reasoning || ''),
      'Move to Pipeline?': pass, // picked up by 'Pipeline - Move to Pipeline'
    };
    if (!row['Headquarters Location'] && r.geography_guess) upd['Headquarters Location'] = r.geography_guess;
    if (NEWS_SOURCES.some(s => String(row['Source'] || '').toLowerCase() === s.toLowerCase()) && r.company_name) {
      upd['Organization Name'] = r.company_name;
    }
    out.push({ json: upd });
  }
});
return out;
